LOCK='5cd64ca89ee9f3ec76d275bc4082349764ac8a5cb4647a9bb9a4eaf267b76ab9'
def load():
 x=json.loads(zlib.decompress(base64.b85decode(PAYLOAD)))
 y=dict(x); claimed=y.pop("canonical_sha256")
 got=hashlib.sha256(json.dumps(y,sort_keys=True,separators=(",",":")).encode()).hexdigest()
 if claimed!=LOCK or got!=LOCK: raise RuntimeError("coordinate-sign retained lock mismatch")
 if x["coordinate_order"]!=["a1","a2","a3","b1","b2","b3","c"]: raise RuntimeError("coordinate order regression")
 if any(len(x["picard_actions_64x64"][n])!=64 or any(len(r)!=64 for r in x["picard_actions_64x64"][n]) for n in x["coordinate_order"]): raise RuntimeError("action shape regression")
 return x
